import{_ as a,o as i,c as n,ai as e}from"./chunks/framework.Duywnu3E.js";const g=JSON.parse('{"title":"6. Настройте IP-туннель между офисами HQ и BR:","description":"","frontmatter":{},"headers":[],"relativePath":"module1/task1-6.md","filePath":"module1/task1-6.md"}'),l={name:"module1/task1-6.md"};function p(t,s,r,h,c,d){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="_6-настроите-ip-туннель-между-офисами-hq-и-br" tabindex="-1">6. Настройте IP-туннель между офисами HQ и BR: <a class="header-anchor" href="#_6-настроите-ip-туннель-между-офисами-hq-и-br" aria-label="Permalink to “6. Настройте IP-туннель между офисами HQ и BR:”">​</a></h1><details class="details custom-block"><summary>Details</summary><ul><li><p>На выбор технологии GRE или IP in IP</p></li><li><p>Сведения о туннеле занесите в отчёт</p></li></ul></details><p>В рамках руководства будем использовать GRE-туннель для связи офисов HQ и BR.</p><h2 id="_6-1-настроика-gre-на-hq-rtr" tabindex="-1">6.1 Настройка GRE на HQ-RTR <a class="header-anchor" href="#_6-1-настроика-gre-на-hq-rtr" aria-label="Permalink to “6.1 Настройка GRE на HQ-RTR”">​</a></h2><p>Создаём конфигурационные файлы для GRE-интерфейса на HQ-RTR.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-RTR</span></span>
<span class="line"><span># /etc/net/ifaces/GRE1/options</span></span>
<span class="line highlighted"><span>TYPE=iptun</span></span>
<span class="line highlighted"><span>TUNTYPE=gre</span></span>
<span class="line highlighted"><span>TUNLOCAL=172.16.1.2</span></span>
<span class="line highlighted"><span>TUNREMOTE=172.16.2.2</span></span>
<span class="line highlighted"><span>TUNTTL=64</span></span>
<span class="line highlighted"><span>TUNOPTIONS=&#39;ttl 64&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li><code>TUNLOCAL</code> — IP-адрес локального интерфейса, через который отправляются пакеты туннеля</li><li><code>TUNREMOTE</code> — IP-адрес удалённого интерфейса, на который приходят пакеты туннеля</li><li><code>HOST</code> — имя физического интерфейса, через который проходит туннельный трафик</li></ul></div><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-RTR</span></span>
<span class="line"><span># /etc/net/ifaces/GRE1/ipv4address</span></span>
<span class="line highlighted"><span>10.0.0.1/30</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_6-2-настроика-gre-на-br-rtr" tabindex="-1">6.2 Настройка GRE на BR-RTR <a class="header-anchor" href="#_6-2-настроика-gre-на-br-rtr" aria-label="Permalink to “6.2 Настройка GRE на BR-RTR”">​</a></h2><p>Аналогично создаём конфигурацию GRE-интерфейса на BR-RTR, зеркально поменяв адреса <code>TUNLOCAL</code> и <code>TUNREMOTE</code>.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># BR-RTR</span></span>
<span class="line"><span># /etc/net/ifaces/GRE1/options</span></span>
<span class="line highlighted"><span>TYPE=iptun</span></span>
<span class="line highlighted"><span>TUNTYPE=gre</span></span>
<span class="line highlighted"><span>TUNLOCAL=172.16.2.2</span></span>
<span class="line highlighted"><span>TUNREMOTE=172.16.1.2</span></span>
<span class="line highlighted"><span>TUNTTL=64</span></span>
<span class="line highlighted"><span>TUNOPTIONS=&#39;ttl 64&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># BR-RTR</span></span>
<span class="line"><span># /etc/net/ifaces/GRE1/ipv4address</span></span>
<span class="line highlighted"><span>10.0.0.2/30</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Применяем сетевую конфигурацию на обеих машинах.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Маршрутизация трафика между офисами через GRE-туннель будет настроена позднее, в рамках конфигурации динамической маршрутизации.</p></div><h2 id="_6-3-проверка-работоспособности" tabindex="-1">6.3 Проверка работоспособности <a class="header-anchor" href="#_6-3-проверка-работоспособности" aria-label="Permalink to “6.3 Проверка работоспособности”">​</a></h2><p>Убедиться в корректной работе туннеля можно пингом между GRE-интерфейсами.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># HQ-RTR</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.0.2</span></span></code></pre></div><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># BR-RTR</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.0.1</span></span></code></pre></div><p>Если пинг идёт — GRE-туннель работает.</p><p>Полезные материалы:</p><ul><li><a href="https://www.altlinux.org/Etcnet#%D0%9D%D0%B0%D1%81%D1%82%D1%80%D0%BE%D0%B9%D0%BA%D0%B0_%D0%B8_%D0%B8%D1%81%D0%BF%D0%BE%D0%BB%D1%8C%D0%B7%D0%BE%D0%B2%D0%B0%D0%BD%D0%B8%D0%B5_IP-%D1%82%D1%83%D0%BD%D0%BD%D0%B5%D0%BB%D0%B5%D0%B9" target="_blank" rel="noreferrer">Etcnet: настройка IP-туннелей</a></li></ul>`,22)])])}const o=a(l,[["render",p]]);export{g as __pageData,o as default};
